def grep(pattern, flags, files):
    flag_set = set(flags)
    line_number = "-n" in flag_set
    list_files = "-l" in flag_set
    ignore_case = "-i" in flag_set
    invert = "-v" in flag_set
    whole_line = "-x" in flag_set
    multiple_files = len(files) > 1

    search_pattern = pattern.casefold() if ignore_case else pattern
    results = []

    for filename in files:
        with open(filename) as file:
            lines = file.read().splitlines()

        file_matches = False
        for number, line in enumerate(lines, start=1):
            candidate = line.casefold() if ignore_case else line
            matches = candidate == search_pattern if whole_line else search_pattern in candidate
            if invert:
                matches = not matches

            if not matches:
                continue

            file_matches = True
            if not list_files:
                prefix = ""
                if multiple_files:
                    prefix += filename + ":"
                if line_number:
                    prefix += str(number) + ":"
                results.append(prefix + line)

        if list_files and file_matches:
            results.append(filename)

    return "\n".join(results)

def grep(pattern, flags, files):
    flag_set = set(flags.split())
    line_number = "-n" in flag_set
    list_files = "-l" in flag_set
    ignore_case = "-i" in flag_set
    invert = "-v" in flag_set
    whole_line = "-x" in flag_set
    multiple_files = len(files) > 1

    search_pattern = pattern.casefold() if ignore_case else pattern
    results = []

    for filename in files:
        file_matches = False
        with open(filename) as file:
            for number, raw_line in enumerate(file, start=1):
                line = raw_line.rstrip("\n\r")
                candidate = line.casefold() if ignore_case else line
                matches = (candidate == search_pattern if whole_line else search_pattern in candidate)
                if invert:
                    matches = not matches
                if not matches:
                    continue

                file_matches = True
                if not list_files:
                    prefix = filename + ":" if multiple_files else ""
                    if line_number:
                        prefix += str(number) + ":"
                    results.append(prefix + line)

        if list_files and file_matches:
            results.append(filename)

    return "\n".join(results) + ("\n" if results else "")

class RestAPI:
    def __init__(self, database=None):
        self.users = {}
        if database:
            source = database.get("users", []) if isinstance(database, dict) else database
            for user in source:
                if isinstance(user, str):
                    self.users[user] = {"name": user, "owes": {}, "owed_by": {}}
                else:
                    name = user["name"]
                    self.users[name] = {
                        "name": name,
                        "owes": dict(user.get("owes", {})),
                        "owed_by": dict(user.get("owed_by", {})),
                    }

    def _user(self, name):
        user = self.users[name]
        owes = dict(user.get("owes", {}))
        owed_by = dict(user.get("owed_by", {}))
        balance = sum(owed_by.values()) - sum(owes.values())
        return {
            "name": name,
            "owes": owes,
            "owed_by": owed_by,
            "balance": balance,
        }

    def get(self, url, payload=None):
        if url != "/users":
            return None
        names = payload.get("users") if payload else None
        if names is None:
            names = sorted(self.users)
        else:
            names = sorted(names)
        return {"users": [self._user(name) for name in names]}

    def post(self, url, payload=None):
        payload = payload or {}
        if url == "/add":
            name = payload["user"]
            self.users[name] = {"name": name, "owes": {}, "owed_by": {}}
            return self._user(name)

        if url == "/iou":
            lender = payload["lender"]
            borrower = payload["borrower"]
            amount = payload["amount"]
            if lender == borrower:
                return {"users": [self._user(lender)]}

            borrower_data = self.users[borrower]
            lender_data = self.users[lender]
            reverse = borrower_data["owed_by"].get(lender, 0)

            if reverse >= amount:
                remaining = reverse - amount
                if remaining:
                    borrower_data["owed_by"][lender] = remaining
                    lender_data["owes"][borrower] = remaining
                else:
                    borrower_data["owed_by"].pop(lender, None)
                    lender_data["owes"].pop(borrower, None)
            else:
                borrower_data["owed_by"].pop(lender, None)
                lender_data["owes"].pop(borrower, None)
                net = amount - reverse
                borrower_data["owes"][lender] = net
                lender_data["owed_by"][borrower] = net

            return {"users": [self._user(name) for name in sorted((lender, borrower))]}

        return None

