class BowlingGame:
    def __init__(self):
        self._rolls = []

    def _validate_rolls(self, rolls):
        if any(not isinstance(pins, int) or isinstance(pins, bool) or pins < 0 or pins > 10 for pins in rolls):
            raise ValueError("pins must be an integer between 0 and 10")

        index = 0

        for frame in range(1, 10):
            if index >= len(rolls):
                return False

            first = rolls[index]
            index += 1

            if first == 10:
                continue

            if index >= len(rolls):
                return False

            second = rolls[index]
            index += 1
            if first + second > 10:
                raise ValueError("pins knocked down in a frame cannot exceed 10")

        remaining = len(rolls) - index
        if remaining == 0:
            return False
        if remaining > 3:
            raise ValueError("too many rolls in the game")

        first = rolls[index]
        if remaining == 1:
            return False

        second = rolls[index + 1]

        if first == 10:
            if second != 10 and remaining == 3:
                if second + rolls[index + 2] > 10:
                    raise ValueError("fill balls cannot knock down more than 10 pins")
            return remaining == 3

        if first + second > 10:
            raise ValueError("pins knocked down in the tenth frame cannot exceed 10")

        if first + second == 10:
            return remaining == 3

        if remaining == 3:
            raise ValueError("an open tenth frame cannot have a bonus roll")
        return True

    def roll(self, pins):
        candidate = self._rolls + [pins]
        if len(candidate) > 21:
            raise ValueError("cannot roll after the game is complete")

        self._validate_rolls(candidate)
        self._rolls.append(pins)

    def score(self):
        if not self._validate_rolls(self._rolls):
            raise ValueError("cannot score an incomplete game")

        total = 0
        index = 0

        for _ in range(9):
            first = self._rolls[index]
            if first == 10:
                total += 10 + self._rolls[index + 1] + self._rolls[index + 2]
                index += 1
                continue

            second = self._rolls[index + 1]
            frame_score = first + second
            if frame_score == 10:
                frame_score += self._rolls[index + 2]
            total += frame_score
            index += 2

        total += sum(self._rolls[index:])
        return total

def can_chain(dominoes):
    if not dominoes:
        return True

    stones = list(dominoes)
    used = [False] * len(stones)

    def search(start_value, current_value, placed):
        if placed == len(stones):
            return current_value == start_value

        for index, domino in enumerate(stones):
            if used[index]:
                continue

            left, right = domino
            if left == current_value:
                used[index] = True
                if search(start_value, right, placed + 1):
                    return True
                used[index] = False

            if right != left and right == current_value:
                used[index] = True
                if search(start_value, left, placed + 1):
                    return True
                used[index] = False

        return False

    for index, domino in enumerate(stones):
        left, right = domino
        used[index] = True

        if search(left, right, 1):
            return True

        if right != left and search(right, left, 1):
            return True

        used[index] = False

    return False

def can_chain(dominoes):
    if not dominoes:
        return []

    stones = list(dominoes)
    used = [False] * len(stones)
    chain = []

    def search(start, current):
        if len(chain) == len(stones):
            return current == start

        for index, (left, right) in enumerate(stones):
            if used[index]:
                continue

            if left == current:
                used[index] = True
                chain.append((left, right))
                if search(start, right):
                    return True
                chain.pop()
                used[index] = False

            if right != left and right == current:
                used[index] = True
                chain.append((right, left))
                if search(start, left):
                    return True
                chain.pop()
                used[index] = False

        return False

    for index, (left, right) in enumerate(stones):
        used[index] = True
        chain.append((left, right))
        if search(left, right):
            return chain
        chain.pop()
        used[index] = False

        if right != left:
            used[index] = True
            chain.append((right, left))
            if search(right, left):
                return chain
            chain.pop()
            used[index] = False

    return None

def proverb(items, qualifier=None):
    if not items:
        return ""

    verses = [
        f"For want of a {current} the {next_item} was lost."
        for current, next_item in zip(items, items[1:])
    ]

    description = f"{qualifier} " if qualifier else ""
    verses.append(f"And all for the want of a {description}{items[0]}.")
    return "\n".join(verses)

def proverb(*items, qualifier=None):
    if not items:
        return []

    verses = [
        f"For want of a {current} the {next_item} was lost."
        for current, next_item in zip(items, items[1:])
    ]
    description = f"{qualifier} " if qualifier else ""
    verses.append(f"And all for the want of a {description}{items[0]}.")
    return verses
